import { test, expect } from '@playwright/test';

test.describe('ARIA Landmarks for Page Regions', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/page-with-landmarks');
  });

  test('should define page regions using ARIA landmarks', async ({ page }) => {
    // Verify main content region exists
    const mainContent = page.getByRole('main');
    await expect(mainContent).toBeVisible();
    await expect(mainContent).toHaveAttribute('aria-label', /main content/);

    // Verify header region exists
    const header = page.getByRole('banner');
    await expect(header).toBeVisible();
    await expect(header).toHaveAttribute('aria-label', /header/);

    // Verify navigation region exists
    const nav = page.getByRole('navigation');
    await expect(nav).toBeVisible();
    await expect(nav).toHaveAttribute('aria-label', /navigation/);

    // Verify main content has correct heading structure
    const mainHeading = page.getByRole('heading', { name: /main content/ });
    await expect(mainHeading).toBeVisible();
    await expect(mainHeading).toHaveAttribute('aria-level', '1');

    // Verify footer region exists
    const footer = page.getByRole('contentinfo');
    await expect(footer).toBeVisible();
    await expect(footer).toHaveAttribute('aria-label', /footer/);

    // Verify sidebar region exists
    const sidebar = page.getByRole('complementary');
    await expect(sidebar).toBeVisible();
    await expect(sidebar).toHaveAttribute('aria-label', /sidebar/);
  });

  test('should handle missing or invalid ARIA landmarks gracefully', async ({ page }) => {
    // Intercept API call to simulate missing landmark data
    await page.route('**/api/page-data', route => {
      route.abort('failed');
    });

    // Reload page to test error handling
    await page.reload();

    // Verify error message is displayed
    const errorMessage = page.getByText(/page content could not be loaded/);
    await expect(errorMessage).toBeVisible();

    // Verify main content area is still accessible with fallback
    const mainContent = page.getByRole('main');
    await expect(mainContent).toBeVisible();
    await expect(mainContent).toContainText('Fallback content');

    // Verify navigation still functions
    const nav = page.getByRole('navigation');
    await expect(nav).toBeVisible();
    await expect(nav).toContainText('Home');

    // Verify footer is still present
    const footer = page.getByRole('contentinfo');
    await expect(footer).toBeVisible();
  });
});
